# Disable Network Throttling Index Write-Host "Disabling network throttling index..." -ForegroundColor Cyan # Set NetworkThrottlingIndex to FFFFFFFF (disabled) for both AC and DC power Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "NetworkThrottlingIndex" -Value 0xFFFFFFFF -Type DWord -Force -ErrorAction Stop # Set SystemResponsiveness to 0 (minimum, gives more CPU to network) Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "SystemResponsiveness" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "Network throttling has been disabled." -ForegroundColor Green Write-Host "Network performance during gaming and streaming should improve." -ForegroundColor Gray